// === Tab: mySketch ===
let step = 24;
let margin = 300;
let MAX = 30;
let A = new Array(MAX);

class Attract {
  x;
  y;
  vx;
  vy;

  constructor() {
    x = random(width);
    y = random(height);
    let rad=random(TWO_PI);
    vx=cos(rad)*8;
    vy=sin(rad)*8;
  }

  function update() {
    x+=vx;
    if (x<0 || x>width) {
      vx=-vx;
      x+=vx*2;
    }
    y+=vy;
    if (y<0 || y>width) {
      vy=-vy;
      y+=vy*2;
    }
  }
}

function setup() {
  createCanvas(640, 2000);
  stroke(255);
  noFill();
  for (i=0; i<MAX; i++) {
    A[i] = new Attract();
  }
}

function draw() {
  background(0);
  let f=radians(frameCount);
  for (let a of A) {
    a.update();
  }
  for (y=step/2-margin; y<width+margin; y+=step) {
    beginShape();
    for (x=step/2-margin; x<height+margin; x+=step) {
      let dx=0;
      let dy=0;
      for (let a of A) {
        let dis = dist(a.x, a.y, x, y);
        dx+=(a.x-x)/dis*map(cos(f), -1, 1, 8, 12);
        dy+=(a.y-y)/dis*map(sin(f/PI), -1, 1, 20, 26);
      }
      curveVertex(x+dx, y+dy);
      strokeWeight(3);
      point(x+dx, y+dy);
    }
    strokeWeight(1);
    endShape();
  }
}

